rows = [
[7],[],[3,7,9],[],[1,2],[7],[5],[5],[],[],[],[8],[],[0,8],[4],[1,4,10],[],[0],[],[],[3,4,9],[5,7],[1],[3,7],[],[],[],[5,9]
]
R,C=28,11
g=[[1]*C for _ in range(R)]
for r,cs in enumerate(rows):
    for c in cs:g[r][c]=7
# Connect successive markers within each row/column using 3.
for r in range(R):
    cs=rows[r]
    for a,b in zip(cs,cs[1:]):
        for c in range(a+1,b): g[r][c]=3
for c in range(C):
    rs=[r for r in range(R) if g[r][c]==7]
    for a,b in zip(rs,rs[1:]):
        for r in range(a+1,b): g[r][c]=3
import json
print(json.dumps(g,separators=(',',':')))
